  ["Show the welcome at every login"] = "Mostrar as boas-vindas em todo login",
  ["Sit by a fire together, share it with your group, a camp ring for the evening."] = "Sentar juntos ao redor de uma fogueira, compartilhá-la com seu grupo, um anel de acampamento para a noite.",
  ["Switch on %s on the Suite page."] = "Ative %s na página Suíte.",
  ["Talk to a quest giver with the conversation on"] = "Falar com quem dá missões com a conversa ativada",
  ["Talk to people without quest windows"] = "Falar com as pessoas sem janelas de missão",
  ["Text"] = "Texto",
  ["The Gestures ring"] = "O anel do Gestures",
  ["The Orbiter"] = "O Orbiter",
  ["The Orbiter plays Spoken's voices for quests, places, books and bosses, and the game's voice where Spoken has none."] = "O Orbiter reproduz as vozes do Spoken para missões, lugares, livros e chefes, e a voz do jogo onde o Spoken não tem.",
  ["The Orbiter plays the zone's story."] = "O Orbiter reproduz a história da zona.",
  ["The campfire"] = "A fogueira",
  ["The hub: every app's settings, the Suite page, Help."] = "O hub: as configurações de cada aplicativo, a página Suíte, a Ajuda.",
  ["The land speaks"] = "A terra fala",
  ["The land tells its stories as you walk (the Orbiter with Spoken)"] = "A terra conta suas histórias enquanto você caminha (o Orbiter com o Spoken)",
  ["The screen for the view"] = "A tela para a paisagem",
  ["The search opens a page for anything."] = "A busca abre uma página para qualquer coisa.",
  ["The suite's button at the minimap"] = "O botão da suíte no minimapa",
  ["The suite's words"] = "As palavras da suíte",
  ["The way there, by road, flight and boat"] = "O caminho até lá, por estrada, voo e barco",
  ["The welcome stays away at login; the General page brings it back."] = "As boas-vindas não aparecem no login; a página Geral as traz de volta.",
  ["The welcome window at every login, until Don't show again in its corner (plan-launch-version D)."] = "A janela de boas-vindas em todo login, até Não mostrar novamente no canto dela (plan-launch-version D).",
  ["Try it"] = "Experimentar",
  ["What matters for this way"] = "O que importa neste caminho",
  ["What you get"] = "O que você recebe",
  ["Where things are"] = "Onde ficam as coisas",
  ["You know the way."] = "Você já conhece o caminho.",
  ["Your first five minutes"] = "Seus primeiros cinco minutos",
  ["Your gestures on a ring, thanks in your own words"] = "Seus gestos em um anel, agradecimentos com suas próprias palavras",
  ["Your pack"] = "Sua mochila",
  -- the welcome's information layer (02.11.2026)
  ["Highpeak"] = "Pico Alto",
  ["Greenback Ridge"] = "Cume Dorsoverde",
  ["Peacebloom"] = "Florpaz",
  ["%d yd high, %d yd away"] = "%d jd de altura, a %d jd",
  ["%d yd away"] = "a %d jd",
  -- the artist's credit under a hand-drawn dungeon map (ADR 0048, 02.11.2026)
  ["Map by %s"] = "Mapa de %s",
  ["Map by %s (%s), used with kind permission. Thank you!"] = "Mapa de %s (%s), usado com gentil permissão. Obrigado!",
  ["Click, then Ctrl+C to copy the address"] = "Clique e depois Ctrl+C para copiar o endereço",
  -- the minimap buttons
  ["Welcome"] = "Boas-vindas",
  ["Its own minimap button for the welcome"] = "Seu próprio botão no minimapa para as boas-vindas",
  ["A button at the minimap that shows the welcome with the Wanderer and the Scholar again."] = "Um botão no minimapa que mostra de novo as boas-vindas com o Andarilho e o Erudito.",
  ["%s is switched off. Its page has the switch to turn it on."] = "%s está desativado. A página dele tem o interruptor para ativá-lo.",
  ["Click: its page, to switch it on."] = "Clique: a página dele, para ativá-lo.",
  -- What's new (ADR 0021, LG5): the release notes, keyed by their English text
  ["Quests: right-click a quest in your log to abandon it; the game asks first."] = "Missões: clique com o botão direito em uma missão do seu registro para abandoná-la; o jogo pergunta antes.",
  ["Chat: the Up and Down keys recall your sent lines on Forever too (Alt+Up stays the game's)."] = "Chat: as setas para cima e para baixo recuperam suas linhas enviadas também no Forever (Alt+Cima continua sendo do jogo).",
  ["Orbiter: hovering a quest mark shows the quest's chain position and its rewards (money, reputation, items)."] = "Orbiter: ao passar o mouse sobre uma marca de missão, aparecem sua posição na cadeia e as recompensas (dinheiro, reputação, itens).",
  ["Quests: the zone view no longer errors on quests that are new in Forever."] = "Missões: a visão de zona não dá mais erro em missões novas no Forever.",
  ["Core: no catalogue warning when a voice line starts or a quest reward loads."] = "Core: sem aviso de catálogo quando uma fala começa ou uma recompensa de missão carrega.",
  ["Bastian's minimap shows the herbs, ore and creatures your tracking finds on its own styles too, and the game's tracking button is back in its tools row."] = "O minimapa do Bastian mostra também, nos próprios estilos, as ervas, minérios e criaturas que o seu rastreamento encontra, e o botão de rastreamento do jogo voltou à barra de ferramentas.",
  ["The session plan (what fits into the next 30 to 180 minutes) moved from Route's Explore to Bastian's Gold and is off until you switch it on in Gold's settings."] = "O plano de sessão (o que cabe nos próximos 30 a 180 minutos) mudou do Explorar do Route para o Bastian's Gold e fica desligado até você ativá-lo nas configurações do Gold.",
  ["Other addons can ask Bastian's for any thing's name and places, your notes near a spot and your gold income through Bastians.API."] = "Outros addons podem perguntar ao Bastian's, pela Bastians.API, o nome e os lugares de qualquer coisa, suas notas perto de um ponto e sua renda de ouro.",
  ["When Bastian's Helpers restocks an item, it tells you if another vendor sells it cheaper and where."] = "Quando o Bastian's Helpers repõe um item, ele avisa se outro vendedor o vende mais barato e onde.",
  ["What's new speaks your language: German, French, Spanish, Korean and Chinese."] = "As novidades falam sua língua: alemão, francês, espanhol, coreano e chinês.",
  ["An item's price page shows a small chart of the prices your own auction house scans saw over the last two weeks."] = "A página de preço de um item mostra um pequeno gráfico dos preços que suas próprias varreduras da casa de leilões viram nas últimas duas semanas.",
  ["Mail rules: tell Helpers which character gets your herbs, ore, cloth and more, and one click beside the send tab fills the mail."] = "Regras de correio: diga ao Helpers qual personagem recebe suas ervas, minérios, tecidos e mais; um clique ao lado da aba de envio preenche a carta.",
  ["Campfire can share your fire on a public channel and show everyone's fires (off by default, with a block list)."] = "O Campfire pode compartilhar sua fogueira em um canal público e mostrar as fogueiras de todos (desligado por padrão, com uma lista de bloqueio).",
  ["Bastian's Suite now speaks Russian and Brazilian Portuguese."] = "O Bastian's Suite agora fala russo e português do Brasil.",
  ["A Gestures command can now cast, use and target: /cast and friends run as a macro when you click the wedge."] = "Um comando do Gestures agora pode conjurar, usar e selecionar alvo: /cast e companhia rodam como macro ao clicar na fatia.",
  ["Other addons can now read and set Bastian's waypoint, read the account's gold and the suite's item sets through Bastians.API."] = "Outros addons agora podem ler e definir o ponto de rota do Bastian's, ler o ouro da conta e os conjuntos de itens da suíte pela Bastians.API.",
  ["Spoken 3.8.0, the launch client's copy, is now the version the suite was tested with; the hub no longer flags it as newer."] = "O Spoken 3.8.0, a versão do cliente de lançamento, agora conta como testado; o hub não o marca mais como mais novo.",
  ['"Show on map" now draws what you chose (its icon and name at every place) and selects it, even when its layer is off.'] = '"Mostrar no mapa" agora desenha o que você escolheu (seu ícone e nome em cada lugar) e o seleciona, mesmo quando a camada dele está desligada.',
  ['one search syntax in every box (words, "phrases", OR, -not, field:value, level>30), the text keys Ctrl+Backspace/Delete/Left/Right, a key that clears the screen for role play, a lock on every window, and the new look engine behind Modern and WoW.'] = 'uma só sintaxe de busca em cada caixa (palavras, "frases", OR, -não, campo:valor, level>30), as teclas de texto Ctrl+Backspace/Delete/Left/Right, uma tecla que limpa a tela para roleplay, uma trava em cada janela, e o novo motor de visual por trás do Modern e do WoW.',
  ['Bastian\'s Helpers also writes its notices into a chat tab named "Addons" when you have one.'] = 'O Bastian\'s Helpers também escreve seus avisos em uma aba de chat chamada "Addons", quando você tem uma.',
  ['The colour picker opens in front of the settings, and no "blocked" message appears in combat.'] = 'O seletor de cores abre na frente das configurações, e nenhuma mensagem de "bloqueado" aparece em combate.',
  ["The game's voice that reads quest texts is a woman's by default and can be chosen in the Orbiter's settings."] = "A voz do jogo que lê os textos das missões é feminina por padrão e pode ser escolhida nas configurações do Orbiter.",
  ["Without Spoken, the Orbiter reads a quest's text with the game's own voice (Accessibility settings)."] = "Sem o Spoken, o Orbiter lê o texto de uma missão com a voz do próprio jogo (configurações de acessibilidade).",
  ["Bastian's Orbiter (the Voice addon, renamed): the panel keeps its place and grows around its middle, says what it plays and what a click did, has pictogram controls and its own minimap button; the game's settings pages of the suite scroll."] = "Bastian's Orbiter (o addon Voice, renomeado): o painel mantém seu lugar e cresce a partir do centro, diz o que está tocando e o que um clique fez, tem controles com pictogramas e seu próprio botão no minimapa; as páginas de configuração da suíte no jogo rolam.",
  ["Bastian's Voice: Play on quests, zones, areas, bosses and books where Spoken has a line, the Lore Orbit around you, and quest conversations without the game's windows (off by default)."] = "Bastian's Voice: Tocar em missões, zonas, áreas, chefes e livros onde o Spoken tem uma fala, a Órbita de Histórias ao seu redor e conversas de missão sem as janelas do jogo (desligado por padrão).",
  ["A note you add on a dungeon's page (or any other page) now shows on that page."] = "Uma nota adicionada à página de uma masmorra (ou de qualquer outra página) agora aparece nessa página.",
  ["The minimap's search finds only NPCs, quests, zones, your notes and bookmarks, and marks the place it jumps to; a quest marks its quest giver."] = "A busca do minimapa encontra apenas PNJs, missões, zonas, suas notas e favoritos, e marca o lugar para onde salta; uma missão marca quem a oferece.",
  ["The map has a Dungeons and raids layer, and it switches on by itself when you pick a dungeon in the Browser."] = "O mapa tem uma camada Masmorras e raides, que liga sozinha quando você escolhe uma masmorra no Navegador.",
  ["New app Bastian's Helpers: sells junk, repairs, restocks, takes all mail, helps at quest givers and shows IDs on tooltips."] = "Novo app Bastian's Helpers: vende lixo, conserta, reabastece, pega toda a correspondência, ajuda com quem dá missões e mostra IDs nas dicas.",
  ["The dungeon pages name the right bosses; some showed an unrelated creature (Shadowfang Keep's first boss as Archaedas) with loot that was not its own."] = "As páginas de masmorras nomeiam os chefes certos; algumas mostravam uma criatura sem relação (o primeiro chefe do Bastilha da Presa Negra como Archaedas) com saque que não era dela.",
  ["Minimap buttons close what they opened; Gestures' button opens its options; a switched-off app's button leads to its switch; a new button shows the welcome again."] = "Os botões do minimapa fecham o que abriram; o botão de Gestos abre suas opções; o botão de um app desligado leva ao seu interruptor; um botão novo mostra as boas-vindas de novo.",
  ["Forever's own dungeons (Dalaran, the Wetlands excavation, the Hall of Thanes, the Ruins of Lordaeron) now show Santiago Reyes' hand-drawn maps with the bosses marked - thank you, Santiago!"] = "As masmorras próprias do Forever (Dalaran, a escavação nos Pantanais, o Salão dos Thanes, as Ruínas de Lordaeron) agora mostram os mapas desenhados à mão por Santiago Reyes com os chefes marcados - obrigado, Santiago!",
  ["German, French and Spanish players read most quests' whole texts in their language, and the AddOn list speaks every language of the suite."] = "Jogadores alemães, franceses e espanhóis leem os textos completos da maioria das missões no seu idioma, e a lista de AddOns fala todos os idiomas da suíte.",
  ["The game's AddOn list shows the suite as one folding \"Bastian's Suite\" header with the data packs and map styles folded under their app, in Korean and Chinese too."] = 'A lista de AddOns do jogo mostra a suíte como um cabeçalho recolhível "Bastian\'s Suite", com os pacotes de dados e os estilos de mapa recolhidos sob o seu app, também em coreano e chinês.',
  ["Korean and Chinese players read the quests' whole texts in their language, and Bastian's Chat speaks French, Spanish, Korean and Chinese."] = "Jogadores coreanos e chineses leem os textos completos das missões no seu idioma, e o Bastian's Chat fala francês, espanhol, coreano e chinês.",
  ["With Total RP 3 or MyRolePlay, Chat, Gestures and the Orbiter show other players' roleplay names."] = "Com o Total RP 3 ou o MyRolePlay, o Chat, os Gestos e o Orbiter mostram os nomes de roleplay dos outros jogadores.",
  ["A new welcome: choose the Wanderer or the Scholar with a picture of your own race, set up your pack, and try your first five minutes step by step."] = "Novas boas-vindas: escolha o Andarilho ou o Erudito com uma imagem da sua raça, monte seu pacote e experimente seus primeiros cinco minutos passo a passo.",
  ["Bastian's Campfire: a card while a fire is near, a camp ring in Gestures, share the fire with your group and guild, and a planner of every camp feature."] = "Bastian's Campfire: um cartão enquanto há uma fogueira perto, um anel de acampamento nos Gestos, compartilhar a fogueira com seu grupo e guilda, e um planejador de todos os itens de acampamento.",
  ["Emotes in Bastian's Chat now show in the colour scheme's own emote colour, for roleplay."] = "Os emotes no Bastian's Chat agora aparecem na cor de emote do próprio esquema de cores, para roleplay.",
  ["A Gestures wedge can run one of your own macros with a click, and runs the game's own commands such as /reload; Quests' item buttons work with \"cast on key down\"."] = 'Uma fatia dos Gestos pode executar um dos seus próprios macros com um clique e executa os comandos do próprio jogo, como /reload; os botões de item das Missões funcionam com "lançar ao pressionar a tecla".',
  ["The Korean and Chinese texts of the suite read naturally and use the game's own terms."] = "Os textos em coreano e chinês da suíte soam naturais e usam os termos do próprio jogo.",
  ["Build your Gestures rings as you like: name them, pick any emote, your own lines, commands, the suite's and the game's controls through one filter; the wheel turns the right way; a conversation's choices no longer overlap on the Orbiter."] = "Monte seus anéis de Gestos como quiser: dê nomes, escolha qualquer emote, suas próprias falas, comandos, os controles da suíte e do jogo por um único filtro; a roda gira para o lado certo; as escolhas de uma conversa não se sobrepõem mais no Orbiter.",
  ["When someone challenges, trades or invites you, Gestures offers a bow, a wave or a polite decline; Chat's + menu has a Roleplay tab."] = "Quando alguém desafia, negocia ou convida você, os Gestos oferecem uma reverência, um aceno ou uma recusa educada; o menu + do Chat tem uma aba Roleplay.",
  ["Gestures' Route home, Mark heard and Toggle the tracker wedges light up."] = "As fatias de Gestos Rota para casa, Marcar como ouvido e Alternar o rastreador acendem.",
  ["The Orbiter says when your Spoken is newer or older than the suite was tested with, never talks over Spoken or Spoken Players, and Bastian's Helpers, Chat and the Orbiter show up on broker displays; other addons can ask who knows a recipe, let the Orbiter speak, read your play preset and open any app."] = "O Orbiter avisa quando seu Spoken é mais novo ou mais antigo do que a versão com que a suíte foi testada, nunca fala por cima do Spoken ou do Spoken Players, e o Bastian's Helpers, o Chat e o Orbiter aparecem em painéis de broker; outros addons podem perguntar quem conhece uma receita, fazer o Orbiter falar, ler seu estilo de jogo e abrir qualquer app.",
  ["Every app wears its own mark on the minimap, in the hub, on broker displays and in the AddOns list: a compass star for the suite, a scroll for Quests, a pin for the Map, a lens for the Browser, a balance for Gold, a signpost for Route, a quill for Notes, two characters for Alts, a wrench for Helpers, bubbles for Chat, a hand for Gestures."] = "Cada app usa sua própria marca no minimapa, na central, nos painéis de broker e na lista de AddOns: uma rosa dos ventos para a suíte, um pergaminho para as Missões, um alfinete para o Mapa, uma lupa para o Navegador, uma balança para o Ouro, uma placa para a Rota, uma pena para as Notas, dois personagens para os Personagens, uma chave inglesa para os Auxiliares, balões para o Chat, uma mão para os Gestos.",
  ["Choose how you play at the first start: the Wanderer hears Azeroth with nearly no UI, the Scholar has every quest, creature, item and place one click away; Bastian's Gestures brings emote rings and courtesy; the hub explains every app and key."] = "Escolha como jogar no primeiro início: o Andarilho ouve Azeroth quase sem interface, o Erudito tem cada missão, criatura, item e lugar a um clique; o Bastian's Gestures traz anéis de emotes e cortesia; a central explica cada app e tecla.",
  ["Every button shows its pictogram again and the words sit where they belong; chat tabs and buttons are easy to tell apart; the Orbiter's controls click with a creature shown, its hub drags it, and its answers are symbols; an item's page says which of your characters has it."] = "Cada botão mostra seu pictograma de novo e as palavras ficam no lugar certo; abas e botões do chat são fáceis de distinguir; os controles do Orbiter respondem ao clique com uma criatura mostrada, seu centro o arrasta e suas respostas são símbolos; a página de um item diz qual dos seus personagens o tem.",
  ["Trainers say what they train on the map and on their page, and their list of spells shows who of your characters knows each one; item lists filter by who owns an item; the Orbiter hides with the clear-screen key and drags by its hub; the Browser's hover preview is a setting."] = "Os instrutores dizem no mapa e na sua página o que ensinam, e sua lista de feitiços mostra qual dos seus personagens conhece cada um; as listas de itens filtram por quem tem o item; o Orbiter se esconde com a tecla de limpar a tela e é arrastado pelo centro; a prévia ao passar o mouse no Navegador é uma configuração.",
  ["Every app offers a data-broker feed (Titan, Bazooka, ElvUI and the like), the Addon Compartment lists the suite, bag addons get the suite's item sets, and other addons can read the suite through Bastians.API."] = "Cada app oferece um feed de data broker (Titan, Bazooka, ElvUI e similares), o Compartimento de Addons lista a suíte, addons de bolsa recebem os conjuntos de itens da suíte, e outros addons podem ler a suíte pelo Bastians.API.",
  ["The Orbiter's bubbles glide to their places and the one that plays is coloured; Show on map always draws what you chose; the junk filter also cleans the lines already on screen; the game's voice is found once the client lists it."] = "As bolhas do Orbiter deslizam para seus lugares e a que está tocando fica colorida; Mostrar no mapa sempre desenha o que você escolheu; o filtro de lixo também limpa as linhas que já estão na tela; a voz do jogo é encontrada assim que o cliente a lista.",
  ["Seven looks to pick from, including Night, Glass and Parchment; every button of the suite shows a pictogram; every colour scheme is checked for readable text."] = "Sete visuais para escolher, incluindo Noite, Vidro e Pergaminho; cada botão da suíte mostra um pictograma; cada esquema de cores é verificado quanto à legibilidade do texto.",
  ["the Browser's filter pills use the pane's width and the first row is never hidden, the Mobs search works again, zones appear once, a preview needs Shift, and a note saved on a page shows at once."] = "os botões de filtro do Navegador usam a largura do painel e a primeira linha nunca fica escondida, a busca de Monstros funciona de novo, as zonas aparecem uma vez, uma prévia precisa de Shift, e uma nota salva em uma página aparece na hora.",
  ["The map's layer bar names each icon the moment you point at it."] = "A barra de camadas do mapa nomeia cada ícone no momento em que você aponta para ele.",
  ["Other addons can ask Bastian's for prices, quest state, the active route and travel times, start a route, and listen to its events through Bastians.API."] = "Outros addons podem pedir ao Bastian's preços, o estado das missões, a rota ativa e os tempos de viagem, iniciar uma rota e ouvir seus eventos pelo Bastians.API.",
  ["Wide buttons in the WoW look keep the game's rounded ends instead of stretching them."] = "Botões largos no visual WoW mantêm as pontas arredondadas do jogo em vez de esticá-las.",
  ["Bastian's apps show in Titan Panel, Bazooka, EllesmereUI's data bars and every other LibDataBroker display, in the addon compartment, and sort your bags in BetterBags, Baganator and AdiBags."] = "Os apps do Bastian's aparecem no Titan Panel, no Bazooka, nas barras de dados do EllesmereUI e em qualquer outro painel LibDataBroker, no compartimento de addons, e organizam suas bolsas no BetterBags, no Baganator e no AdiBags.",
  ["Bastian's Chat gets a live tab filter, tab windows that dock back, a Messenger of the WhatsApp kind with class icons and a search, and a lock on every chat window."] = "O Bastian's Chat ganha um filtro de abas ao vivo, janelas de aba que voltam a se encaixar, um Messenger no estilo do WhatsApp com ícones de classe e busca, e uma trava em cada janela de chat.",
})
